import { shopPhotos } from "./photos.js";

/**
 * Gallery data.
 *
 * The photographs are real, owner-supplied images of the SmartphoneCafe store
 * (see src/data/photos.js, generated by scripts/process-shop-photos.mjs).
 * Alt text and captions follow the owner's own descriptive filenames.
 */

/**
 * Gallery ordering: the strongest wide frames lead, and the low-resolution
 * storefront shot is deliberately placed later so it is never rendered at a
 * size its 732px source cannot support.
 */
export const galleryPhotos = [
  shopPhotos.find((p) => p.id === "interior"),
  shopPhotos.find((p) => p.id === "ownerWithCustomer"),
  shopPhotos.find((p) => p.id === "products"),
  shopPhotos.find((p) => p.id === "customerService"),
  shopPhotos.find((p) => p.id === "counterService"),
  shopPhotos.find((p) => p.id === "interiorWide"),
  shopPhotos.find((p) => p.id === "inStoreService"),
  shopPhotos.find((p) => p.id === "customer"),
  shopPhotos.find((p) => p.id === "storefront"),
].filter(Boolean);

